pub fn inspect_first<F: FnOnce(&u8)>(callback: F) -> std::vec::Vec<std::boxed::Box<u8>> {
    let mut values = std::vec::Vec::<std::boxed::Box<u8>>::new();
    std::vec::Vec::push(&mut values, std::boxed::Box::new(7_u8));
